 3	namespace Modules\AI\Actions;
 4	
 5	use Exception;
 6	use Modules\AI\Contracts\QueueAiBuilding;
 7	use Modules\AI\Enums\AiQueueActionReason;
 8	use Modules\AI\Support\AiActionResult;
 9	use OGame\Factories\PlanetServiceFactory;
10	use OGame\GameObjects\Models\Enums\GameObjectType;
11	use OGame\Models\BuildingQueue;
12	use OGame\Models\Planet;
13	use OGame\Services\BuildingQueueService;
14	use OGame\Services\ObjectService;
15	use OGame\Services\PlayerGameStateService;
16	
17	/**
18	 * Module-owned adapter over the normal OGameX building queue.
19	 *
20	 * It refreshes a fresh actor and delegates to the existing authoritative queue
21	 * service; it does not add an AI contract or rule to the host application.
22	 */
23	class QueueAiBuildingAction implements QueueAiBuilding
24	{
25	    public function __construct(
26	        private PlayerGameStateService $playerGameStateService,
27	        private PlanetServiceFactory $planetServiceFactory,
28	        private BuildingQueueService $buildingQueueService,
29	    ) {
30	    }
31	
32	    public function handle(int $playerId, int $planetId, int $buildingId): AiActionResult
33	    {
34	        if (!Planet::query()->whereKey($planetId)->where('user_id', $playerId)->exists()) {
35	            return AiActionResult::rejected(AiQueueActionReason::PlanetNotOwned);
36	        }
37	
38	        try {
39	            $player = $this->playerGameStateService->advance($playerId, $planetId);
40	
41	            if ($player->isBanned()) {
42	                return AiActionResult::rejected(AiQueueActionReason::PlayerBanned);
43	            }
44	            if ($player->isInVacationMode()) {
45	                return AiActionResult::rejected(AiQueueActionReason::VacationMode);
46	            }
47	
48	            $planet = $this->planetServiceFactory->makeForPlayer($player, $planetId, false);
49	            $building = ObjectService::getObjectById($buildingId);
50	            if ($building->type !== GameObjectType::Building && $building->type !== GameObjectType::Station) {
51	                return AiActionResult::rejected(AiQueueActionReason::NotABuilding);
52	            }
53	            // The host's own predicate: the two unit-producing stations cannot be upgraded while
54	            // ships or defence are in production. The module names no object here.
55	            if ($player->isObjectUpgradeBlocked($buildingId)) {
56	                return AiActionResult::rejected(AiQueueActionReason::ShipyardBusy);
57	            }
58	
59	            $this->buildingQueueService->add($planet, $buildingId);
60	            $queueId = BuildingQueue::query()
61	                ->where('planet_id', $planetId)
62	                ->where('object_id', $buildingId)
63	                ->latest('id')
64	                ->value('id');
65	
66	            return $queueId === null ? AiActionResult::rejected(AiQueueActionReason::QueueNotCreated) : AiActionResult::queued($queueId);
67	        } catch (Exception $exception) {
68	            return AiActionResult::rejected($exception->getMessage());
69	        }
70	    }
71	}
